code.cpp:
class Solution {
public:
    int maximumValue(vector<string>& strs) {
        int maxVal = 0;
        for (const string& s : strs) {
            bool allDigits = all_of(s.begin(), s.end(), [](char c) {
                return isdigit(c);
            });
            int val = allDigits ? stoi(s) : (int)s.size();
            maxVal = max(maxVal, val);
        }
        return maxVal;
    }
};
